            const visH = p.oy - sink;
            if (visH > 0) ctx2.drawImage(p.canvas, 0, 0, p.w, visH, c.x - p.ox + Math.round(Math.sin(t * 40) * 2 * (1 - k2)), c.y - p.oy + sink, p.w, visH);
