        eye: [".......", "..###..", ".#...#.", "#..#..#", ".#...#.", "..###..", "......."],
        wave: [".......", ".##..##", "#..##..", ".......", ".##..##", "#..##..", "......."],
        star: ["...#...", "...#...", "#######", ".#####.", "..###..", ".##.##.", ".#...#."]
