          this.iceMotes = new Motes(40, { x0: 0, y0: sy + 10, x1: W6, y1: H6 - 40 }, { seed: 8, vx: [-3, 3], vy: [-2, 2], sizes: [1], colors: ["#ffffff", "#c8fbff", NEON_ICE], alpha: [0.5, 1], wob: 6 });
          this.nearMotes = new Motes(24, { x0: 0, y0: sy + 10, x1: W6, y1: H6 - 30 }, { seed: 9, vx: [-4, 4], vy: [1, 5], sizes: [2, 2, 3], colors: ["#f0fcff", "#d0f4ff"], alpha: [0.12, 0.3], wob: 8 });
