          this.slush.update(dt * (0.6 + wx.snow * 0.6 + wx.bliz * 0.6), drift, 0);
          this.iceMotes.update(dt, drift * 0.6, 0);
          this.nearMotes.update(dt, drift * 1.3, 0);
          this.airSnow.update(dt * (0.6 + wx.bliz * 1.4), 8 + wx.bliz * 160, wx.bliz * 40);
