          let top = H6;
          for (let x = 0; x <= W6; x++) if (ys[x] < top) top = ys[x];
          const water = this.waterBlend.get([[this.water.day, tod.day], [this.water.dusk, tod.dusk], [this.water.night, tod.night]]);
          const view = env.view;
