            const stretch = 1 + s * 0.05 * k;
            const rightPage = dir > 0 === showFront;
            const col = rightPage ? u : pw - 1 - u;
            const hh = Math.round(ph * stretch);
            const yy = Math.round(y0 - lift - (hh - ph) / 2);
