          ctx2.fillStyle = "#05080c";
          ctx2.fillRect(mm.x - 2, mm.y - 2, mm.w + 4, mm.h + 4);
          ctx2.fillStyle = BRASS3[2];
          ctx2.fillRect(mm.x - 1, mm.y - 1, mm.w + 2, mm.h + 2);
          ctx2.fillStyle = BRASS3[4];
          ctx2.fillRect(mm.x - 1, mm.y - 1, mm.w + 2, 1);
          ctx2.fillStyle = rgba("#06121c", 0.92);
          ctx2.fillRect(mm.x, mm.y, mm.w, mm.h);
