          ctx2.fillRect(vx, vy, vw, vh);
          ctx2.fillStyle = ui.hover(mm) || this.mmDrag ? "#ffffff" : "#ffe27a";
          ctx2.fillRect(vx, vy, vw, 1);
          ctx2.fillRect(vx, vy + vh - 1, vw, 1);
          ctx2.fillRect(vx, vy, 1, vh);
          ctx2.fillRect(vx + vw - 1, vy, 1, vh);
