            const x0 = s < 0 ? fx - 50 : fx;
            ctx2.fillStyle = BRASS3[3];
            ctx2.fillRect(x0, r.y + 13, 50, 1);
            ctx2.fillStyle = BRASS3[0];
            ctx2.fillRect(x0, r.y + 14, 50, 1);
            ctx2.fillStyle = BRASS3[4];
            ctx2.fillRect(fx - 1, r.y + 12, 3, 3);
            ctx2.fillStyle = BRASS3[5];
